'use server'

import { cookies } from 'next/headers'
import { revalidatePath } from 'next/cache'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications')?.value === 'on'
  const next = !current

  cookieStore.set('notifications', next ? 'on' : 'off', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
  })

  revalidatePath('/')
}

import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsOn = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <button type="submit">
          Notifications: {notificationsOn ? 'On' : 'Off'}
        </button>
      </form>
    </main>
  )
}
